import { lazy } from 'react';
import type { SectionVariant } from './shared';

function deferred(load: () => Promise<Record<string, unknown>>, group: string, id: string) {
  return lazy(async () => {
    const variants = (await load())[group] as SectionVariant[];
    const variant = variants.find(v => v.id === id);
    if (!variant) throw new Error(`Unknown section variant: ${group}/${id}`);
    return { default: variant.Component };
  });
}

